 if(a==='send'){if(!it.no){it.no=`TWR-TMC-${it.trade}-${it.type}-042`;}Object.assign(it,{stage:'internal',step:'cpm',holder:'ali',wk:.2});it.log.push(E('send',m,at,{int:1,note:p&&p.note}));V.mode='detail';V.tab='det';V.viewer='ce';return L(`Sent to Ali Sonour · ${it.no}`,`أُرسل إلى علي سنور · ${it.no}`)}
