 if(['A','B','C','D'].includes(a)){Object.assign(it,{stage:'closed',code:a,step:null,holder:null});it.log.push(E(a,m,at,{sign:1,note:p&&p.note}));if(a==='B')it.cmts=p.rows.length;if(a==='C')it.cmtsC=[p.note];return L(`Code ${a} issued ✍ · ${a==='B'?p.rows.length+' comments sent to the Snag List':'sealed PDF created'}`,`صدر Code ${a} ✍`)}
